fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Requires that the input matrix is non-empty and all rows have the same length
    // Ensures that the output matrix is the transpose of the input matrix
    // Invariant: The transposed matrix is being filled correctly
    // Decreases: The number of rows remaining to process

    // Precondition: arr is a non-empty matrix with at least one row and one column
    assert!(!arr.is_empty() && !arr[0].is_empty());
    let rows = arr.len();
    let cols = arr[0].len();

    // Ensure all rows have the same length
    for row in &arr {
        assert!(row.len() == cols);
    }

    // Create a new matrix for the transposed result with dimensions cols x rows
    let mut transposed = vec![vec![0; rows]; cols];

    // Fill the transposed matrix
    for i in 0..rows {
        // Invariant: transposed[0..j][i] is correctly filled for all j < cols
        for j in 0..cols {
            // Ensure that we are within bounds of the input matrix
            assert!(i < rows && j < cols);
            transposed[j][i] = arr[i][j];
        }
    }

    // Postcondition: The transposed matrix has dimensions cols x rows
    // and transposed[j][i] == arr[i][j] for all valid i, j
    assert!(transposed.len() == cols);
    for j in 0..cols {
        assert!(transposed[j].len() == rows);
        for i in 0..rows {
            assert!(transposed[j][i] == arr[i][j]);
        }
    }

    transposed
}